-- Daily challenges for 2026-10-02: two new themes, 365 to-dos each.
-- Generated by tools/challenges_sql.py --since 2026-10-02

-- The templates: an upsert on slug, so a re-run keeps every id.
insert into public.challenge_templates
  (slug, title, description, category, total_days, tags, min_level, published_at)
values
  ('easing-back-into-work', 'Easing Back into Work', 'For anyone returning to work after a break, a leave, a vacation or a long stretch away. Each day is one small step that makes the return steadier, so you can settle back in without trying to catch up on everything at once.', 'Work', 365, array['Work', 'Life Transitions', 'Stress']::text[], 1, '2026-10-02T17:00:00+00:00'::timestamptz),
  ('being-a-good-neighbor', 'Being a Good Neighbor', 'For anyone who barely knows the people living around them. Each day is one small, low-pressure way to be friendly, helpful or simply noticed on your street, in your building or in your town, so home feels a little more like a community.', 'Kindness', 365, array['Relationships', 'Loneliness']::text[], 1, '2026-10-02T17:00:00+00:00'::timestamptz)
on conflict (slug) do update set
  title        = excluded.title,
  description  = excluded.description,
  category     = excluded.category,
  total_days   = excluded.total_days,
  tags         = excluded.tags,
  min_level    = excluded.min_level,
  published_at = excluded.published_at;

-- The bank of to-dos for each of those templates, replaced wholesale.
delete from public.challenge_days d
  using public.challenge_templates t
  where d.template_id = t.id and t.slug in ('easing-back-into-work', 'being-a-good-neighbor');

